"""Text helpers shared by the claim form and the ledger bridge."""
import unicodedata

_SPACES = {"\t", "\n", "\r", "\x0b", "\x0c", " ", "　"}


def normalize(text):
    """NFC-normalize, turn odd whitespace into plain spaces, collapse runs."""
    if text is None:
        return ""
    text = unicodedata.normalize("NFC", str(text))
    out = []
    for ch in text:
        if ch in _SPACES:
            ch = " "
        elif unicodedata.category(ch) == "Cc":
            continue
        if ch == " " and out and out[-1] == " ":
            continue
        out.append(ch)
    return "".join(out).strip()


def clip_chars(text, limit):
    """Cut text to at most `limit` characters (never splits a character)."""
    if limit <= 0:
        return ""
    if len(text) <= limit:
        return text
    return text[:limit].rstrip()


def clip_utf8(text, max_bytes):
    """Cut text to at most `max_bytes` UTF-8 bytes on a character boundary."""
    if max_bytes <= 0:
        return ""
    if len(text.encode("utf-8")) <= max_bytes:
        return text
    out, used = [], 0
    for ch in text:
        size = len(ch.encode("utf-8"))
        if used + size > max_bytes:
            break
        out.append(ch)
        used += size
    return "".join(out).rstrip()


def display_width(text):
    """Terminal/report column width: East Asian wide characters count as 2."""
    width = 0
    for ch in text:
        width += 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1
    return width


def pad_display(text, width):
    """Pad (or cut) text so that it occupies exactly `width` report columns."""
    out, used = [], 0
    for ch in text:
        w = display_width(ch)
        if used + w > width:
            break
        out.append(ch)
        used += w
    return "".join(out) + " " * (width - used)
"""Date helpers (ISO strings only; no time zones involved)."""
import calendar
import datetime as _dt


def parse_date(value):
    try:
        return _dt.date.fromisoformat(str(value).strip())
    except ValueError:
        raise ValueError(f"invalid date: {value!r}") from None


def month_of(value):
    d = parse_date(value)
    return f"{d.year:04d}-{d.month:02d}"


def month_bounds(month):
    """Inclusive first and last day of a YYYY-MM month as ISO strings."""
    year, mon = (int(x) for x in month.split("-"))
    last = calendar.monthrange(year, mon)[1]
    return f"{year:04d}-{mon:02d}-01", f"{year:04d}-{mon:02d}-{last:02d}"


def previous_month(month):
    year, mon = (int(x) for x in month.split("-"))
    if mon == 1:
        return f"{year - 1:04d}-12"
    return f"{year:04d}-{mon - 1:02d}"

