"""Ledger status of a claim, read from the period listing (never from `show`).

`show` is priced per call by the vendor, so it stays with the finance desk.
A claim is booked when its receipt appears in the ledger listing for the
month it was spent in. The listing is fetched on every call, not cached,
so the screen always reflects the ledger's current state.
"""
from hbexpense.models import POSTED
from hbexpense.util.dates import month_bounds, month_of

BOOKED = "booked"
NOT_BOOKED = "not_booked"


class LedgerStatusService:
    def __init__(self, ledger):
        self.ledger = ledger

    def for_claim(self, claim):
        return self.for_claims([claim])[claim.claim_id]

    def for_claims(self, claims):
        """{claim_id: "booked" | "not_booked" | None}, one listing per month."""
        settled = [c for c in claims if c.status == POSTED and c.receipt]
        receipts_by_month = {}
        for claim in settled:
            month = month_of(claim.spent_on)
            if month not in receipts_by_month:
                date_from, date_to = month_bounds(month)
                rows = self.ledger.list_rows(date_from, date_to)
                receipts_by_month[month] = {row.receipt for row in rows}
        statuses = {claim.claim_id: None for claim in claims}
        for claim in settled:
            found = claim.receipt in receipts_by_month[month_of(claim.spent_on)]
            statuses[claim.claim_id] = BOOKED if found else NOT_BOOKED
        return statuses

